#!/usr/bin/env node
/**
 * scripts/eval-recall.mjs — T-021 C4. Builds the real tree from `data/toc-migrated/*` (same
 * `tsx/esm/api` `register()` pattern as `scripts/seed-toc.mjs`), runs `computeRecallAtK` against
 * the real golden set (`data/eval/golden-set.json`, generated by `gen-golden-set.mjs`) using the
 * heuristic (non-LLM) retriever, prints recall@5 + every miss, and writes
 * `data/eval/recall-report.json`. No live network call, no live Mongo — local files only.
 */
// dotenv: the vector mode needs MONGODB_URL and GEMINI_API_KEY. Without it `connect()` silently
// fell back to localhost and failed with ECONNREFUSED against a host that was never the target.
import "dotenv/config";
import { readdirSync, readFileSync, writeFileSync, existsSync } from "node:fs";
import { basename, join, dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { register } from "tsx/esm/api";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const DATA_DIR = join(ROOT, "data", "toc-migrated");
const GOLDEN_SET_PATH = join(ROOT, "data", "eval", "golden-set.json");
// One report file PER RETRIEVER. The vector run previously wrote over
// `recall-report.json` — i.e. it destroyed the heuristic baseline that its own delta is measured
// against, so a second run would have had nothing left to compare to. Separate files keep both
// numbers on disk and comparable.
const REPORT_PATH = join(ROOT, "data", "eval", "recall-report.json");
const VECTOR_REPORT_PATH = join(ROOT, "data", "eval", "recall-report-vector.json");
const HYBRID_REPORT_PATH = join(ROOT, "data", "eval", "recall-report-hybrid.json");
const PROVENANCE_PATH = join(ROOT, "data", "eval", "golden-set-provenance.json");
const REJECTED_PATH = join(ROOT, "data", "eval", "golden-set-rejected.json");
const K = 5;

register(); // let subsequent dynamic import()s of packages/index's .ts sources resolve

function loadJson(path) {
  return JSON.parse(readFileSync(path, "utf8"));
}

/**
 * ISS-271: pure filterBias decision — testable without Mongo/network. `measured: false` fires
 * ONLY when `rejectedPathExists` is false (the old bug: absence fell through to a bare `null`,
 * indistinguishable from "measured, no bias found"). `computeRejected`/`computeCombined` are
 * thunks, called only when `rejectedQs` is non-empty, so this function has no I/O of its own.
 */
export function computeFilterBias({ rejectedPathExists, rejectedQs, keptResult, computeRejected, computeCombined }) {
  if (!rejectedPathExists) {
    return {
      measured: false,
      note:
        "NOT MEASURED — data/eval/golden-set-rejected.json is absent, so the ISS-092 filter-bias " +
        "check did not run on this report. This is not a claim of zero bias; re-run " +
        "scripts/gen-golden-set.mjs to produce the rejected-candidates file, then re-run this " +
        "script to measure it.",
    };
  }
  if (rejectedQs.length === 0) {
    return {
      measured: true,
      note:
        "0 candidates rejected, so the kept set IS the candidate set and the filter introduces " +
        "no selection bias on this run — kept === combined by construction",
      kept: { n: keptResult.total, recallAtK: keptResult.recallAtK },
      rejected: { n: 0, recallAtK: null },
      combined: { n: keptResult.total, recallAtK: keptResult.recallAtK },
    };
  }
  const rejectedResult = computeRejected();
  const combined = computeCombined();
  return {
    measured: true,
    note:
      "the post-filter removes questions the retriever tends to answer, so `kept` is a " +
      "downward-biased floor; `combined` is the pre-filter figure",
    kept: { n: keptResult.total, recallAtK: keptResult.recallAtK },
    rejected: { n: rejectedResult.total, recallAtK: rejectedResult.recallAtK },
    combined: { n: combined.total, recallAtK: combined.recallAtK },
  };
}

/**
 * Embeds every golden-set question in ONE batched call and loads the tenant's real chunk rows.
 *
 * Hoisted out of the retriever deliberately: `RetrieveFn` is synchronous, so the network call
 * cannot live inside it. Doing it here also means 92 questions cost one batched request rather
 * than 92, and the `chunks` come from the live collection rather than a fixture — the whole point
 * of U1.4 is that its number is measured against real vectors.
 */
async function embedQuestionsAndLoadChunks(questions, tenantId, opts = {}) {
  const { connect, close, getDb, scopedCollection } = await import("../packages/db/src/index.ts");
  const { embed: routeEmbed } = await import("../packages/ai/src/index.ts");
  const { buildRouting } = await import("../apps/api/src/production.ts");

  await connect(process.env.MONGODB_URL || "mongodb://localhost:27017", process.env.MONGODB_DB || "lkb");
  try {
    const chunks = await scopedCollection(getDb(), "chunks")(tenantId).find({}).toArray();
    if (chunks.length === 0) {
      throw new Error(`eval-recall --retriever vector: tenant "${tenantId}" has no chunks; run scripts/backfill-chunks.mjs first`);
    }
    const { chains, providers } = buildRouting();
    const texts = questions.map((q) => q.question);
    // purpose "query", not "document": Gemini embeds the two asymmetrically, and embedding a
    // question as a document is a real (silent) recall regression.
    // This is an offline evaluator: it may READ live chunks, but must never mutate the jobs ledger.
    const embedded = await routeEmbed("embedding", { kind: "embedding", texts, purpose: "query" },
      { chains, providers, write: async () => {}, tenantId });
    if (embedded.vectors.length !== texts.length) {
      throw new Error(`eval-recall: embedder returned ${embedded.vectors.length} vectors for ${texts.length} questions`);
    }
    const questionVectors = new Map(texts.map((t, i) => [t, embedded.vectors[i]]));
    // Turns are loaded only for the hybrid arm; the vector run must not pay for a 2118-row read
    // it does not use.
    const turns = opts.withTurns
      ? await scopedCollection(getDb(), "turns")(tenantId).find({}).toArray()
      : [];
    return { questionVectors, chunks, model: embedded.model, turns };
  } finally {
    await close();
  }
}

async function main() {
  const { buildTree } = await import("../packages/index/src/tree/build.ts");
  const { computeRecallAtK } = await import("../packages/index/src/eval/recall.ts");
  const { createHeuristicRetriever } = await import("../packages/index/src/eval/heuristic-retriever.ts");
  const { createNullRetriever, assessBaseline } = await import("../packages/index/src/eval/baseline.ts");

  const sessionDirs = readdirSync(DATA_DIR, { withFileTypes: true })
    .filter((d) => d.isDirectory()).map((d) => d.name);

  const sessions = [];
  const sessionPages = [];
  for (const id of sessionDirs) {
    const sessionPath = join(DATA_DIR, id, "session.json");
    const pagePath = join(DATA_DIR, id, "session_page.json");
    if (existsSync(sessionPath)) sessions.push(loadJson(sessionPath));
    if (existsSync(pagePath)) sessionPages.push(loadJson(pagePath));
  }

  const roots = buildTree(sessions, sessionPages);
  const tenantId = sessions[0]?.tenantId;
  const tree = roots[tenantId];
  if (!tree) throw new Error(`eval-recall: no tree built for tenantId "${tenantId}"`);

  const questions = loadJson(GOLDEN_SET_PATH);

  // `--retriever vector` (U1.4) scores the brute-force cosine retriever over the REAL `chunks`
  // rows instead of the tree heuristic, so both numbers come out of the same harness, the same
  // golden set and the same control — which is the only way the delta means anything. Everything
  // below this point is retriever-agnostic and deliberately untouched.
  const retrieverArg = process.argv.includes("--retriever")
    ? process.argv[process.argv.indexOf("--retriever") + 1]
    : "heuristic";
  const useVector = retrieverArg === "vector";
  // `--retriever hybrid` (U1.5 C7). U1.5 must measure its OWN recall rather than inherit U1.4's
  // number, so the merge is scored through the SAME harness, the same golden set and the same
  // question-blind control — which is the only way the three numbers are comparable.
  const useHybrid = retrieverArg === "hybrid";
  let retrieverName = "heuristic";
  let latency = null;
  let retrieve = createHeuristicRetriever(tree);
  if (useHybrid) {
    const { createVectorRetriever } = await import("../packages/index/src/vector/retriever.ts");
    const { createHeuristicRetriever: heur } = await import("../packages/index/src/eval/heuristic-retriever.ts");
    const { rrfMerge } = await import("../packages/ask/src/merge.ts");
    const { lexicalSearchTurns } = await import("../packages/index/src/index.ts");
    const { questionVectors, chunks, model, turns } = await embedQuestionsAndLoadChunks(questions, tenantId, { withTurns: true });
    const vectorRetrieve = createVectorRetriever(questionVectors, chunks);
    const treeRetrieve = heur(tree);
    retrieve = (question, kk) => {
      // Each arm produces ranked SESSION IDS; fusing them is exactly what askV2 does with nodes,
      // so the same rrfMerge is reused rather than a second implementation that could drift.
      const treeArm = treeRetrieve(question, kk);
      const vectorArm = vectorRetrieve(question, kk);
      // ISS-170: the SHIPPED depth is `k` turns, not `k*4`. `ask-arms.ts`'s lexical arm calls
      // `lexicalSearchTurns(query, turns, k)` and THEN dedupes by session, so it can collapse to
      // one or two sessions. Reading 4x deeper here gave the eval a lexical arm strictly stronger
      // than production's, which is measuring a policy that does not ship.
      const seen = new Set();
      const lexArm = [];
      for (const h of lexicalSearchTurns(question, turns, kk)) {
        if (seen.has(h.sessionId)) continue;
        seen.add(h.sessionId);
        lexArm.push(h.sessionId);
      }
      return rrfMerge([treeArm, vectorArm, lexArm], { keyOf: (id) => id }).slice(0, kk);
    };
    // ISS-170: the tree arm is NAMED as the proxy it is. `heuristic-retriever.ts`'s own header says
    // it is "NOT a claim that this measures the real pipeline's recall"; the shipped tree arm is
    // `selectNodes`, an LLM call. Any reader of this report must see that in the retriever string
    // rather than having to know it — the number characterises a near neighbour of what ships.
    retrieverName =
      `hybrid (tree=HEURISTIC PROXY not the shipped selectNodes LLM arm; + cosine + lexical@k, ` +
      `RRF, ${model}, ${chunks.length} chunks)`;
  } else if (useVector) {
    const { createVectorRetriever } = await import("../packages/index/src/vector/retriever.ts");
    const { questionVectors, chunks, model } = await embedQuestionsAndLoadChunks(questions, tenantId);
    retrieve = createVectorRetriever(questionVectors, chunks);
    retrieverName = `vector (brute-force cosine, ${model}, ${chunks.length} chunks)`;
    // p95 over the RANKING only (plan section 10 U1.4's Verify line). The batched embed is excluded
    // deliberately: it is one network round-trip amortised over every question, so folding it in
    // would report network latency as retrieval latency. This is the number that justifies choosing
    // brute force over an ANN index, so it is measured rather than asserted.
    const timings = [];
    for (const q of questions) {
      const t0 = performance.now();
      retrieve(q.question, K);
      timings.push(performance.now() - t0);
    }
    timings.sort((a, b) => a - b);
    const at = (p) => timings[Math.min(timings.length - 1, Math.floor(p * timings.length))];
    latency = {
      unit: "ms",
      note: `ranking only, ${chunks.length} chunks x ${questionVectors.values().next().value.length} dims, excludes the batched embed`,
      n: timings.length,
      p50: +at(0.5).toFixed(2),
      p95: +at(0.95).toFixed(2),
      max: +timings[timings.length - 1].toFixed(2),
    };
  }
  const result = computeRecallAtK(questions, retrieve, K);

  // The control (plan §10 U0.10): a question-blind retriever over the same golden set. A recall
  // number with no control cannot be read — it says nothing about whether the retriever is good
  // or the task is trivial. The session id list comes from the same real sessions the tree was
  // built from, so the control faces exactly the candidate pool the real retriever does.
  const controlIds = sessions.map((s) => s._id);
  const control = computeRecallAtK(questions, createNullRetriever(controlIds), K);
  const assessment = assessBaseline(result, control, controlIds.length);

  /**
   * MEASURE THE POST-FILTER'S BIAS, because it is not neutral (ISS-092).
   *
   * The generator's pin check rejects any question containing a token unique to its own session
   * *within the corpus the retriever scores*. That is the right criterion for stopping keyword
   * shortcuts — and it means the filter preferentially removes exactly the questions this
   * retriever finds easy. The kept-set recall is therefore a DOWNWARD-BIASED FLOOR, not an
   * unbiased estimate of retrieval quality.
   *
   * Reporting the floor alone would understate the retriever and, worse, hide that the number
   * moves with the filter. So score the rejected questions too and publish all three. This turns
   * a reviewer's one-off observation into a figure that is recomputed on every run.
   */
  let rejectedQs = [];
  if (existsSync(REJECTED_PATH)) {
    const rejectedRaw = loadJson(REJECTED_PATH);
    rejectedQs = rejectedRaw.map((r, i) => ({
      id: `rejected-${String(i + 1).padStart(3, "0")}`,
      question: r.question,
      expectedSessionId: r.sessionId,
    }));
  }
  const filterBias = computeFilterBias({
    rejectedPathExists: existsSync(REJECTED_PATH),
    rejectedQs,
    keptResult: result,
    computeRejected: () => computeRecallAtK(rejectedQs, retrieve, K),
    computeCombined: () => computeRecallAtK([...questions, ...rejectedQs], retrieve, K),
  });
  if (!filterBias.measured) {
    console.log("filter bias: NOT MEASURED — golden-set-rejected.json is absent (see filterBias.measured)");
  } else if (filterBias.rejected.n === 0) {
    console.log("filter bias: none — 0 candidates rejected, so kept === combined");
  } else {
    console.log(
      `filter bias: kept ${filterBias.kept.recallAtK.toFixed(3)} (n=${filterBias.kept.n}) | ` +
        `rejected ${filterBias.rejected.recallAtK.toFixed(3)} (n=${filterBias.rejected.n}) | ` +
        `combined ${filterBias.combined.recallAtK.toFixed(3)} (n=${filterBias.combined.n}) ` +
        `— kept is a FLOOR, not an unbiased estimate`,
    );
  }

  console.log(`recall@${K} = ${result.recallAtK.toFixed(3)} (${result.hits}/${result.total} hits)`);
  console.log(`control (question-blind) = ${control.recallAtK.toFixed(3)} | chance floor = ${assessment.chanceFloor.toFixed(3)}`);
  console.log(`VERDICT: ${assessment.verdict.toUpperCase()} — ${assessment.reason}`);
  if (result.misses.length > 0) {
    console.log(`${result.misses.length} miss(es):`);
    for (const m of result.misses) {
      console.log(`  [${m.id}] expected ${m.expectedSessionId}, got [${m.got.join(", ")}]`);
    }
  }

  const report = {
    generatedAt: new Date().toISOString(),
    k: K,
    retriever: retrieverName,
    ...(latency ? { latency } : {}),
    recallAtK: result.recallAtK,
    total: result.total,
    hits: result.hits,
    misses: result.misses,
    // Without these three the recallAtK above is not interpretable — see baseline.ts's header.
    control: { retriever: "null (question-blind)", recallAtK: control.recallAtK, hits: control.hits },
    assessment,
    // READ, never asserted (ISS-091). This was a hardcoded string describing the set as "verbatim
    // session_page.keyInsights excerpts"; when the set was regenerated the string stayed, so a
    // field whose only purpose is honesty became the report's one false statement. The generator
    // now writes its own provenance and this reads it — a claim about the data, written by
    // whatever produced the data. If it is absent, say so; never substitute a guess.
    goldenSetProvenance: existsSync(PROVENANCE_PATH)
      ? loadJson(PROVENANCE_PATH)
      : "UNKNOWN — data/eval/golden-set-provenance.json is absent, so nothing here describes how " +
        "this golden set was built. Re-run scripts/gen-golden-set.mjs. Treat the score as " +
        "uninterpretable until provenance exists.",
    filterBias,
  };
  writeFileSync(useHybrid ? HYBRID_REPORT_PATH : useVector ? VECTOR_REPORT_PATH : REPORT_PATH, JSON.stringify(report, null, 2) + "\n", "utf8");
  console.log(`wrote ${useHybrid ? HYBRID_REPORT_PATH : useVector ? VECTOR_REPORT_PATH : REPORT_PATH}`);
}

// Guarded (same pattern as scripts/lint-loc.mjs): a test file that imports `computeFilterBias`
// must not also trigger the real Mongo/tree-build/network run just by importing this module.
if (process.argv[1] && import.meta.url.endsWith(basename(process.argv[1]))) {
  main().catch((err) => {
    console.error(err);
    process.exitCode = 1;
  });
}
